const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const route=String(input.route??'').toLowerCase(); const deliveryStatus=String(input.delivery_status??input.status??'').toLowerCase();
const attempts=Number(input.reengagement_attempts??input.attempts??0); const maxAttempts=Number(input.max_reengagement_attempts??3);
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const idempotencyKey=String(input.idempotency_key??'').trim(); const providerMessageId=String(input.provider_message_id??'').trim();
const phone=String(input.recipient_phone??input.seller_phone??'').trim(); const email=String(input.recipient_email??input.seller_email??'').trim();
const sellerResponse=String(input.seller_response??input.inbound_message??'').trim();
let status='needs_review'; let action='review'; let nextWorkflow='WF-349'; let retryChannel=''; let reason='Delivery outcome requires review.';
if(dnc){status='dnc_blocked';action='stop';nextWorkflow='WF-126';reason='DNC protection prevents retry or re-engagement.';}
else if(blockers.length){status='blocked';action='stop';nextWorkflow='WF-126';reason='Active blocker prevents retry or re-engagement.';}
else if(sellerResponse){status='seller_response_received';action='route_response';nextWorkflow='WF-342';reason='Seller response takes priority over retry logic.';}
else if(!dealId||!leadId||!propertyId||!idempotencyKey){status='incomplete';action='repair_data';nextWorkflow='WF-349';reason='Required deal identity or idempotency data is missing.';}
else if(['failed','undelivered','rejected','bounced'].includes(deliveryStatus)){
  if(attempts>=maxAttempts){status='max_attempts_reached';action='pause';nextWorkflow='WF-126';reason='Maximum provider retry/re-engagement attempts reached.';}
  else if(phone){status='retry_ready';action='retry';retryChannel='sms';nextWorkflow='WF-347';reason='Delivery failure permits one controlled retry using the available SMS channel.';}
  else if(email){status='retry_ready';action='retry';retryChannel='email';nextWorkflow='WF-347';reason='Delivery failure permits one controlled retry using the available email channel.';}
  else{status='recipient_unavailable';action='human_review';nextWorkflow='WF-126';reason='No usable seller contact channel remains.';}
}
else if(route==='delivered_waiting_response'){status='awaiting_response';action='wait';nextWorkflow='WF-351';reason='Delivery succeeded; do not send duplicate outreach before timeout/cadence gate.';}
else{status='needs_review';action='review';nextWorkflow='WF-349';reason='Delivery event does not authorize autonomous retry.';}
const retryIdempotencyKey=idempotencyKey? idempotencyKey+':retry:'+String(attempts+1):null;
const activity={activity_type:'delivery_failure_retry_controller',subject:'WF-350 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status,action,retry_channel:retryChannel,reengagement_attempts:attempts,max_reengagement_attempts:maxAttempts,provider_message_id:providerMessageId,idempotency_key:idempotencyKey,retry_idempotency_key:retryIdempotencyKey,delivery_status:deliveryStatus,dnc,blockers,reason,next_workflow:nextWorkflow};
return [{json:{...input,wf_id:'WF-350',status,action,retry_channel:retryChannel,retry_idempotency_key:retryIdempotencyKey,next_workflow:nextWorkflow,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
